def find_disjoint_subsets(m):
    s = m * (m + 1) // 6
    if m * (m + 1) % 6 != 0:
        return None

    elements = list(range(1, m + 1))
    subsets = []
    for i in range(1, 1 << m):
        subset = []
        current_sum = 0
        for j in range(m):
            if (i >> j) & 1:
                subset.append(elements[j])
                current_sum += elements[j]
        if current_sum == s:
            subsets.append(set(subset))

    for i in range(len(subsets)):
        for j in range(i + 1, len(subsets)):
            if subsets[i].isdisjoint(subsets[j]):
                return subsets[i], subsets[j]
    return None

