        s_val = m * (m + 1) / 6
        if s_val == int(s_val):
            s = int(s_val)
            # dp[s1][s2] is true if we can form sum s1 and s2 using disjoint subsets of {1, ..., m}
            # To save space, use a set of (s1, s2) pairs
            # We only need s1 <= s and s2 <= s.
            # Since (s1, s2) is the same as (s2, s1), we can enforce s1 <= s2.
            dp = set()
